-- ============================================================================
-- DC14 - Well Data Manager PROFESSIONAL (intermediate tier) goes deep.
--
-- The FIRST Professional tier outside petrophysics. Flips (welldata,
-- intermediate) onto the DC1 deep path by inserting its ACTIVE
-- academy_course_structures row, generated from the repo manifest
-- src/content/courses/welldata/intermediate/manifest.json (the structure source
-- of truth; this file was emitted by a generator, not hand-typed), and
-- seeding the module quiz banks (15+15+15+15+15+15 questions) plus the
-- 42-question final exam bank. Answer keys live only here and in the
-- table (no client SELECT policies); the repo lesson content carries no
-- graded questions.
--
-- Every numeric question traces to the welldata teaching oracle and
-- reproduces the live NG6 Professional capstone answer key: the full
-- import pipeline over feet_20.las (start 1493.52001953125 m, stop
-- 1584.9599609375 m, step 0.609619140625 m, 2 curves unit-converted,
-- 4 curve kinds recognised) plus the uniformity verdict on
-- irregular_20 (0, meaning no). That is the same pipeline
-- src/lib/welldataTeaching.js drives and src/components/course/panels/
-- welldata/importLab.test.js pins.
--
-- Tier note: the Associate tier (DC5) owns QC of a single file. This
-- tier owns the import pipeline. The Expert tier owns the six-file
-- campaign aggregates and they are not examined here.
--
-- Bank standard: measured on the length RANK of the correct option
-- before seeding, per the standard introduced with DC12.
--
-- Enrollment grandfathering: enforced_from defaults to now() on first
-- insert, so learners enrolled before this apply finish on the old path;
-- the ON CONFLICT update deliberately leaves enforced_from unchanged on
-- re-seeds. Re-seeding replaces the whole bank for this course-tier;
-- fine while there are no open attempts (open attempts pin question ids).
-- ============================================================================

values ('welldata', 'intermediate', '{"modules":[{"key":"m01-from-qc-to-import","title":"From QC to Import","lesson_keys":["l01-what-this-tier-adds","l02-the-import-pipeline","l03-the-feet-well","l04-the-import-panel-map"]},{"key":"m02-depth-units","title":"Depth Units","lesson_keys":["l01-why-everything-downstream-is-metric","l02-the-conversion-factor","l03-converting-the-depth-column","l04-float32-and-the-digits-you-see","l05-what-a-wrong-factor-costs"]},{"key":"m03-curve-units","title":"Curve Units","lesson_keys":["l01-not-only-the-depth-column","l02-the-sonic-trap","l03-curves-that-do-not-convert","l04-counting-the-conversions"]},{"key":"m04-curve-kinds","title":"Curve Kinds","lesson_keys":["l01-what-a-kind-is","l02-recognising-four-kinds","l03-why-the-index-curve-is-not-a-kind","l04-when-recognition-fails"]},{"key":"m05-step-uniformity","title":"Step Uniformity","lesson_keys":["l01-why-a-uniform-step-matters","l02-the-uniformity-test","l03-a-representative-difference","l04-the-irregular-well","l05-what-to-do-with-an-irregular-log"]},{"key":"m06-the-import-workflow","title":"The Import Workflow","lesson_keys":["l01-the-workflow-end-to-end","l02-quality-control","l03-the-capstone-walkthrough","l04-onward-to-expert"]}]}'::jsonb, 1)
on conflict (app_slug, tier) do update
  set structure = excluded.structure,
      content_version = excluded.content_version,
      active = true,
      updated_at = now();

delete from public.academy_quiz_questions
 where app_slug = 'welldata' and tier = 'intermediate';

